// Spanish for the glossary, keyed by the id in glossary.js. Partial and
// flat; anything missing falls back to English field by field.

const GLOSSARY_ES = {
  'abba': { term: 'Abba', definition: 'Palabra aramea para padre, usada con cariño, como "papá". Jesús la usó para Dios, y los cristianos la rezan al Padre.' },
  'absolution': { term: 'Absolución', definition: 'El perdón de los pecados concedido por un sacerdote en la Confesión, pronunciado en nombre de Cristo y de la Iglesia.' },
  'abstinence': { term: 'Abstinencia', definition: 'Privarse de un alimento, especialmente de carne, como acto de penitencia. Los católicos se abstienen de carne los viernes de Cuaresma.' },
  'acolyte': { term: 'Acólito', definition: 'Ministro litúrgico que asiste al sacerdote o al obispo en el altar. A los acólitos jóvenes se les llama a menudo monaguillos.' },
  'act-of-contrition': { term: 'Acto de contrición', definition: 'Oración de dolor por los propios pecados y de propósito de enmienda, rezada especialmente en la Confesión.' },
  'adoration': { term: 'Adoración', definition: 'El culto que se debe solo a Dios; también la oración ante el Santísimo Sacramento, honrando a Cristo realmente presente.' },
  'advent': { term: 'Adviento', definition: 'El tiempo de cuatro semanas antes de Navidad, tiempo de esperanza y de preparación para la venida de Cristo.' },
  'alb': { term: 'Alba', definition: 'Vestidura blanca y larga que llevan los ministros en la liturgia, y que recuerda la vestidura blanca del Bautismo.' },
  'alleluia': { term: 'Aleluya', definition: 'Aclamación hebrea de alabanza que significa "alabad al Señor", cantada antes del Evangelio excepto en Cuaresma.' },
  'almsgiving': { term: 'Limosna', definition: 'Dar libremente dinero o bienes a los necesitados, como acto de caridad o de penitencia.' },
  'altar': { term: 'Altar', definition: 'La mesa en el centro del presbiterio donde se ofrece el sacrificio de la Misa y donde el pan y el vino se convierten en el cuerpo y la sangre de Cristo.' },
  'altar-server': { term: 'Monaguillo', definition: 'Persona, a menudo joven, que ayuda al sacerdote durante la Misa llevando la cruz, los ciriales y otros objetos.' },
  'ambo': { term: 'Ambón', definition: 'El atril desde el cual se proclaman las Escrituras en la Misa. También llamado facistol.' },
  'ambry': { term: 'Armario de los santos óleos', definition: 'Hornacina o armario en la iglesia donde se guardan los santos óleos bendecidos en la Misa Crismal.' },
  'amen': { term: 'Amén', definition: 'Palabra hebrea que significa "así sea". Se dice al final de las oraciones para expresar asentimiento y fe.' },
  'angel': { term: 'Ángel', definition: 'Ser espiritual creado por Dios, sin cuerpo, que le sirve y actúa como su mensajero.' },
  'annulment': { term: 'Nulidad matrimonial', definition: 'Declaración de la Iglesia de que un matrimonio nunca fue válido desde el principio. Propiamente se llama decreto de nulidad.' },
  'annunciation': { term: 'Anunciación', definition: 'El momento en que el ángel Gabriel anunció a la Virgen María que sería la madre del Salvador.' },
  'anointing-of-the-sick': { term: 'Unción de los enfermos', definition: 'El sacramento en el que una persona gravemente enferma, anciana o moribunda es ungida y se ora por ella pidiendo salud y fortaleza.' },
  'apostle': { term: 'Apóstol', definition: 'El que es enviado. En especial, los doce hombres que Jesús eligió para llevar su enseñanza al mundo; los obispos son sus sucesores.' },
  'apostolic-succession': { term: 'Sucesión apostólica', definition: 'La transmisión ininterrumpida de la autoridad de los apóstoles a los obispos mediante la imposición de las manos.' },
  'ascension': { term: 'Ascensión', definition: 'El regreso de Cristo resucitado al cielo, cuarenta días después de Pascua.' },
  'aspergillum': { term: 'Hisopo', definition: 'El utensilio que se usa para asperjar agua bendita en las bendiciones.' },
  'assembly': { term: 'Asamblea', definition: 'La comunidad de creyentes reunida para celebrar la liturgia como cuerpo de Cristo.' },
  'assumption': { term: 'Asunción', definition: 'La verdad de que la Virgen María fue llevada en cuerpo y alma al cielo al término de su vida terrena. Se celebra el 15 de agosto.' },
  'atheism': { term: 'Ateísmo', definition: 'La negación de la existencia de Dios.' },
  'auxiliary-bishop': { term: 'Obispo auxiliar', definition: 'Obispo nombrado para ayudar al obispo que dirige una diócesis.' },
  'baptism': { term: 'Bautismo', definition: 'El primer sacramento, que lava el pecado original y hace a la persona miembro de la Iglesia y criatura nueva en Cristo.' },
  'baptismal-font': { term: 'Pila bautismal', definition: 'El recipiente o la fuente que contiene el agua que se usa para el Bautismo.' },
  'basilica': { term: 'Basílica', definition: 'Iglesia a la que el papa concede un título especial de honor y ciertos privilegios.' },
  'beatification': { term: 'Beatificación', definition: 'El paso previo a la canonización, en el que el papa declara "beato" a un difunto y digno de un culto público limitado.' },
  'beatitudes': { term: 'Bienaventuranzas', definition: 'Las bendiciones que Jesús enseñó en el Sermón de la montaña, que describen el carácter y la felicidad de los que están cerca de Dios.' },
  'benediction': { term: 'Bendición con el Santísimo', definition: 'Una bendición; en especial el rito en el que se bendice al pueblo con el Santísimo Sacramento.' },
  'bible': { term: 'Biblia', definition: 'El conjunto de escritos sagrados inspirados por Dios, formado por el Antiguo y el Nuevo Testamento. También llamada Sagrada Escritura.' },
  'bishop': { term: 'Obispo', definition: 'Sucesor de los apóstoles que posee la plenitud del Orden sagrado y dirige una diócesis, enseñando, gobernando y santificando a su pueblo.' },
  'blasphemy': { term: 'Blasfemia', definition: 'Hablar o actuar contra Dios de manera burlona o irreverente. Pecado contra el segundo mandamiento.' },
  'blessed-sacrament': { term: 'Santísimo Sacramento', definition: 'La Eucaristía consagrada, el verdadero cuerpo de Cristo, especialmente cuando se reserva en el sagrario.' },
  'blessing': { term: 'Bendición', definition: 'Oración que pide el cuidado de Dios sobre una persona, un lugar o una actividad, hecha a menudo con la señal de la cruz.' },
  'body-of-christ': { term: 'Cuerpo de Cristo', definition: 'El cuerpo de Cristo en la Eucaristía; también toda la Iglesia, de la que Cristo es la cabeza.' },
  'breviary': { term: 'Breviario', definition: 'El libro que contiene la Liturgia de las Horas, la oración diaria de la Iglesia.' },
  'brother': { term: 'Hermano religioso', definition: 'Hombre que hace votos religiosos y vive en comunidad al servicio de la Iglesia, sin estar ordenado.' },
  'calumny': { term: 'Calumnia', definition: 'Dañar la fama de alguien mintiendo sobre esa persona. Pecado contra el octavo mandamiento.' },
  'canon-law': { term: 'Derecho canónico', definition: 'El conjunto oficial de leyes que rige a la Iglesia católica.' },
  'canon-of-scripture': { term: 'Canon de la Escritura', definition: 'La lista oficial de la Iglesia de los libros reconocidos como inspirados por Dios.' },
  'canonization': { term: 'Canonización', definition: 'La declaración solemne del papa de que una persona es santa en el cielo, digna de honor y de imitación por todos los fieles.' },
  'cantor': { term: 'Salmista', definition: 'La persona que dirige el canto durante la liturgia.' },
  'cardinal': { term: 'Cardenal', definition: 'Eclesiástico de alto rango nombrado por el papa como consejero principal; los cardenales eligen al nuevo papa.' },
  'cardinal-virtues': { term: 'Virtudes cardinales', definition: 'Las cuatro virtudes fundamentales de la vida moral: prudencia, justicia, fortaleza y templanza.' },
  'cassock': { term: 'Sotana', definition: 'Vestidura larga, hasta los pies, que llevan los clérigos y los monaguillos; negra para sacerdotes y monaguillos, de otros colores según el rango.' },
  'catechesis': { term: 'Catequesis', definition: 'La enseñanza y la formación de los cristianos en la fe. Quien la imparte es un catequista.' },
  'catechism': { term: 'Catecismo', definition: 'Resumen de la fe católica usado para la instrucción. El oficial es el Catecismo de la Iglesia católica.' },
  'catechumen': { term: 'Catecúmeno', definition: 'Persona que se prepara para la plena iniciación en la Iglesia mediante el estudio, la oración y la reflexión.' },
  'cathedral': { term: 'Catedral', definition: 'La iglesia principal de una diócesis, donde está la cátedra del obispo, desde la cual enseña y gobierna.' },
  'catholic': { term: 'Católico', definition: 'Palabra griega que significa universal. Nombra a la Iglesia extendida por todo el mundo en comunión con el papa.' },
  'celebrant': { term: 'Celebrante', definition: 'El sacerdote que preside la Misa y consagra la Eucaristía.' },
  'celibacy': { term: 'Celibato', definition: 'El estado de permanecer sin casarse para entregarse por entero a Dios y al servicio de la Iglesia.' },
  'chalice': { term: 'Cáliz', definition: 'La copa sagrada que contiene el vino que se convierte en la sangre de Cristo en la Misa.' },
  'chancellor': { term: 'Canciller', definition: 'El responsable principal del archivo y notario de una diócesis.' },
  'charism': { term: 'Carisma', definition: 'Don del Espíritu Santo concedido a una persona o a una comunidad para el bien de la Iglesia.' },
  'charity': { term: 'Caridad', definition: 'Amor a Dios sobre todas las cosas y amor al prójimo por amor de Dios; la mayor de las tres virtudes teologales.' },
  'chastity': { term: 'Castidad', definition: 'La virtud que ordena rectamente la sexualidad según el propio estado de vida. También uno de los votos de la vida religiosa.' },
  'chasuble': { term: 'Casulla', definition: 'La vestidura exterior que lleva el sacerdote en la Misa; su color lo determina la fiesta o el tiempo litúrgico.' },
  'chrism': { term: 'Santo crisma', definition: 'Aceite perfumado consagrado por el obispo, usado en el Bautismo, la Confirmación y el Orden sagrado.' },
  'christ': { term: 'Cristo', definition: 'El título de Jesús, del griego "el Ungido", equivalente al hebreo "Mesías".' },
  'christian-initiation': { term: 'Iniciación cristiana', definition: 'El camino para llegar a ser miembro pleno de la Iglesia por los sacramentos del Bautismo, la Confirmación y la Eucaristía.' },
  'christmas': { term: 'Navidad', definition: 'La fiesta del nacimiento de Jesús, y el tiempo litúrgico que la sigue.' },
  'church': { term: 'Iglesia', definition: 'Todo el pueblo de Dios en el mundo entero; también una diócesis, o la asamblea reunida para el culto.' },
  'ciborium': { term: 'Copón', definition: 'El vaso sagrado con tapa que contiene las hostias consagradas para la Comunión y para reservarlas en el sagrario.' },
  'cincture': { term: 'Cíngulo', definition: 'El cordón que se ata a la cintura sobre el alba.' },
  'clergy': { term: 'Clero', definition: 'Los hombres que han recibido el Orden sagrado y sirven a la Iglesia como diáconos, sacerdotes u obispos.' },
  'cloister': { term: 'Clausura', definition: 'La parte de un monasterio o convento reservada a la comunidad religiosa, separada del mundo.' },
  'college-of-bishops': { term: 'Colegio episcopal', definition: 'El conjunto de los obispos, presidido por el papa, que posee la autoridad de enseñar en la Iglesia.' },
  'college-of-cardinals': { term: 'Colegio cardenalicio', definition: 'El conjunto de los cardenales que asesoran al papa y eligen a su sucesor.' },
  'commandments': { term: 'Mandamientos', definition: 'Las leyes de Dios para la vida moral, sobre todo los diez mandamientos, que Jesús resumió en el amor a Dios y al prójimo.' },
  'communion-of-saints': { term: 'Comunión de los santos', definition: 'La unión espiritual de todos los fieles, vivos y difuntos, en Cristo: en la tierra, en el cielo y en el purgatorio.' },
  'conclave': { term: 'Cónclave', definition: 'La reunión de los cardenales, celebrada en clausura, para elegir a un nuevo papa.' },
  'concupiscence': { term: 'Concupiscencia', definition: 'La inclinación al pecado que permanece en la naturaleza humana como consecuencia del pecado original.' },
  'confession': { term: 'Confesión', definition: 'La acusación de los propios pecados ante un sacerdote; parte esencial del sacramento de la Penitencia y la Reconciliación.' },
  'confirmation': { term: 'Confirmación', definition: 'El sacramento que sella a los bautizados con los dones del Espíritu Santo y los fortalece para la vida cristiana.' },
  'conscience': { term: 'Conciencia', definition: 'La voz interior, dada por Dios, que juzga lo que está bien y lo que está mal y nos llama a hacer el bien y evitar el mal.' },
  'consecration': { term: 'Consagración', definition: 'El acto de hacer santa a una persona o cosa; en la Misa, el momento en que el pan y el vino se convierten en el cuerpo y la sangre de Cristo.' },
  'contemplation': { term: 'Contemplación', definition: 'Oración sin palabras que consiste en descansar en la presencia de Dios.' },
  'contrition': { term: 'Contrición', definition: 'Dolor sincero por el pecado y propósito de no volver a pecar; el corazón de una buena confesión.' },
  'convent': { term: 'Convento', definition: 'Casa donde las religiosas viven en comunidad.' },
  'conversion': { term: 'Conversión', definition: 'Cambio profundo del corazón, que se aparta del pecado y se vuelve hacia Dios.' },
  'cope': { term: 'Capa pluvial', definition: 'Vestidura larga en forma de capa que lleva el sacerdote o el diácono en las procesiones y en algunas celebraciones.' },
  'covenant': { term: 'Alianza', definition: 'Pacto sagrado y vinculante. En la Biblia, el vínculo entre Dios y su pueblo, cumplido en la nueva alianza de Cristo.' },
  'creation': { term: 'Creación', definition: 'El acto por el que Dios hace existir todas las cosas de la nada.' },
  'creed': { term: 'Credo', definition: 'Declaración formal de las creencias centrales de la fe. Los más conocidos son el Credo de los Apóstoles y el Credo Niceno.' },
  'crosier': { term: 'Báculo', definition: 'El cayado de pastor que lleva el obispo como signo de su oficio pastoral.' },
  'crucifix': { term: 'Crucifijo', definition: 'Cruz que lleva la imagen de Cristo crucificado.' },
  'cubit': { term: 'Codo', definition: 'Antigua unidad de longitud, del codo a la punta del dedo, unos cuarenta y cinco centímetros.' },
  'curia': { term: 'Curia', definition: 'Las oficinas y los oficiales que ayudan al obispo, o al papa, a gobernar. La del papa es la Curia romana.' },
  'deacon': { term: 'Diácono', definition: 'Ministro ordenado que ayuda al sacerdote y al obispo en la liturgia, la predicación y las obras de caridad. Unos son permanentes y otros se preparan para el sacerdocio.' },
  'denarius': { term: 'Denario', definition: 'Moneda romana de plata que valía aproximadamente el salario de un día de un jornalero; se menciona a menudo en los Evangelios.' },
  'diocese': { term: 'Diócesis', definition: 'Comunidad regional de parroquias al cuidado de un obispo. También llamada iglesia particular o local.' },
  'disciple': { term: 'Discípulo', definition: 'Seguidor y alumno de Cristo que vive según su enseñanza.' },
  'discernment': { term: 'Discernimiento', definition: 'Escuchar la llamada de Dios y distinguir entre las opciones buenas y las malas.' },
  'doctrine': { term: 'Doctrina', definition: 'Enseñanza oficial de la Iglesia sobre la fe o la moral.' },
  'dogma': { term: 'Dogma', definition: 'Enseñanza central de la fe, definida por la autoridad de la Iglesia y sostenida con el mayor peso.' },
  'domestic-church': { term: 'Iglesia doméstica', definition: 'La familia, la primera y más básica comunidad de fe.' },
  'doxology': { term: 'Doxología', definition: 'Oración de alabanza a la Trinidad, como el Gloria al Padre o el Amén solemne de la Misa.' },
  'easter': { term: 'Pascua', definition: 'La fiesta más grande del año, que celebra la Resurrección de Jesús de entre los muertos.' },
  'eastern-catholic-churches': { term: 'Iglesias católicas orientales', definition: 'Iglesias católicas con su propia liturgia y tradición orientales, en plena comunión con el papa.' },
  'ecumenical-council': { term: 'Concilio ecuménico', definition: 'Asamblea de todos los obispos del mundo, convocada por el papa, para guiar a toda la Iglesia. El Vaticano II fue el más reciente.' },
  'ecumenism': { term: 'Ecumenismo', definition: 'El movimiento hacia la unidad entre los cristianos y hacia un mayor entendimiento entre los creyentes.' },
  'encyclical': { term: 'Encíclica', definition: 'Carta de enseñanza del papa dirigida a toda la Iglesia, y a veces al mundo entero.' },
  'epiphany': { term: 'Epifanía', definition: 'La fiesta que celebra la manifestación de Cristo a las naciones, señalada por la visita de los Reyes Magos.' },
  'eparchy': { term: 'Eparquía', definition: 'El equivalente de una diócesis en las Iglesias católicas orientales.' },
  'eschatology': { term: 'Escatología', definition: 'La enseñanza sobre las últimas realidades: la muerte, el juicio, el cielo, el infierno y el fin del mundo.' },
  'eucharist': { term: 'Eucaristía', definition: 'El sacramento del cuerpo y la sangre de Cristo bajo las apariencias de pan y vino; el centro del culto católico. También llamada la Misa.' },
  'eucharistic-prayer': { term: 'Plegaria eucarística', definition: 'La gran oración de acción de gracias de la Misa, que incluye la consagración, en el corazón de la celebración.' },
  'euthanasia': { term: 'Eutanasia', definition: 'Acción u omisión deliberada que causa la muerte de una persona enferma o moribunda. La Iglesia la rechaza como violación del quinto mandamiento.' },
  'evangelist': { term: 'Evangelista', definition: 'El que difunde el Evangelio; también cada uno de los cuatro autores de los Evangelios: Mateo, Marcos, Lucas y Juan.' },
  'evangelization': { term: 'Evangelización', definition: 'Anunciar el Evangelio de Jesús con la palabra y con el testimonio de la propia vida.' },
  'examination-of-conscience': { term: 'Examen de conciencia', definition: 'Repaso orante de los propios actos a la luz del Evangelio, hecho especialmente antes de la Confesión.' },
  'excommunication': { term: 'Excomunión', definition: 'Pena grave que impide a una persona acercarse a los sacramentos hasta que se arrepienta; su fin es llamarla de vuelta.' },
  'exorcism': { term: 'Exorcismo', definition: 'Oración en el nombre de Cristo para liberar o proteger a una persona o cosa del poder del mal.' },
  'exposition': { term: 'Exposición', definition: 'La colocación de la Eucaristía en el ostensorio para que los fieles adoren a Cristo presente en ella.' },
  'faith': { term: 'Fe', definition: 'Creer en Dios y aceptar todo lo que él ha revelado; la primera de las tres virtudes teologales.' },
  'faithful': { term: 'Fieles', definition: 'Los miembros de la Iglesia, unidos a ella por el Bautismo.' },
  'fall': { term: 'La caída', definition: 'El primer pecado de Adán y Eva, por el que la humanidad perdió su santidad original.' },
  'fasting': { term: 'Ayuno', definition: 'Privarse de comida o bebida como disciplina espiritual o como acto de dolor por el pecado, especialmente en Cuaresma.' },
  'feast': { term: 'Fiesta', definition: 'Celebración litúrgica de rango medio, que honra a un santo importante o un acontecimiento de la vida de Cristo o de la Iglesia.' },
  'feria': { term: 'Feria', definition: 'Día de la semana del año litúrgico en el que no se celebra ninguna fiesta particular.' },
  'fortitude': { term: 'Fortaleza', definition: 'La virtud del valor que se mantiene firme en hacer el bien a pesar de la dificultad; una de las cuatro virtudes cardinales.' },
  'free-will': { term: 'Libre albedrío', definition: 'La capacidad dada por Dios de elegir libremente, base de la responsabilidad moral.' },
  'friar': { term: 'Fraile', definition: 'Miembro de una orden mendicante, como los franciscanos o los dominicos, que vive en comunidad y sirve a la Iglesia entera.' },
  'fruits-of-the-holy-spirit': { term: 'Frutos del Espíritu Santo', definition: 'Las cualidades de una vida guiada por el Espíritu, enumeradas en Gálatas: amor, alegría, paz, paciencia y otras.' },
  'genuflect': { term: 'Genuflexión', definition: 'Doblar brevemente una rodilla, normalmente hacia el sagrario, como signo de reverencia.' },
  'gifts-of-the-holy-spirit': { term: 'Dones del Espíritu Santo', definition: 'Los siete dones que se nos dan para vivir santamente: sabiduría, entendimiento, consejo, fortaleza, ciencia, piedad y temor de Dios.' },
  'gloria': { term: 'Gloria', definition: 'Antiguo himno de alabanza que se canta en la Misa los domingos y las fiestas, y que comienza "Gloria a Dios en el cielo".' },
  'god': { term: 'Dios', definition: 'El Ser supremo, único, eterno y perfectísimo, Creador de todas las cosas, que existe como tres Personas: Padre, Hijo y Espíritu Santo.' },
  'gospel': { term: 'Evangelio', definition: 'La buena noticia de Jesucristo; también cada uno de los cuatro relatos de su vida escritos por Mateo, Marcos, Lucas y Juan.' },
  'grace': { term: 'Gracia', definition: 'El don gratuito e inmerecido de la vida y la ayuda de Dios en nosotros, necesario para la salvación.' },
  'great-commandment': { term: 'Mandamiento principal', definition: 'El resumen que hace Jesús de toda la ley: amar a Dios con todo el corazón y al prójimo como a uno mismo.' },
  'heaven': { term: 'Cielo', definition: 'El estado de vida eterna y felicidad perfecta en unión con Dios.' },
  'hell': { term: 'Infierno', definition: 'El estado de separación eterna de Dios, elegido por quienes lo rechazan hasta el final.' },
  'heresy': { term: 'Herejía', definition: 'El rechazo deliberado de una enseñanza definida de la fe.' },
  'hierarchy': { term: 'Jerarquía', definition: 'El ministerio ordenado de la Iglesia: el papa y los obispos, los sacerdotes y los diáconos.' },
  'holy-communion': { term: 'Sagrada Comunión', definition: 'La recepción de la Eucaristía, el cuerpo y la sangre de Cristo.' },
  'holy-days-of-obligation': { term: 'Fiestas de precepto', definition: 'Fiestas, además de los domingos, en las que los católicos tienen obligación de asistir a Misa.' },
  'holy-orders': { term: 'Orden sagrado', definition: 'El sacramento por el que los hombres son ordenados diáconos, sacerdotes u obispos para servir a la Iglesia.' },
  'holy-see': { term: 'Santa Sede', definition: 'El oficio y la autoridad del papa como obispo de Roma, y el gobierno central de la Iglesia.' },
  'holy-spirit': { term: 'Espíritu Santo', definition: 'La tercera Persona de la Trinidad, el amor de Dios derramado en los creyentes, que guía y santifica a la Iglesia.' },
  'holy-water': { term: 'Agua bendita', definition: 'Agua bendecida para usarse en las bendiciones y para recordar el Bautismo, como al hacer la señal de la cruz al entrar en una iglesia.' },
  'holy-week': { term: 'Semana Santa', definition: 'La semana anterior a la Pascua, desde el Domingo de Ramos, que recuerda la Pasión, la muerte y la Resurrección de Cristo.' },
  'homily': { term: 'Homilía', definition: 'La predicación en la Misa en la que el sacerdote o el diácono explica las Escrituras y las aplica a la vida diaria.' },
  'hope': { term: 'Esperanza', definition: 'La virtud teologal de confiar en las promesas de Dios de la vida eterna y en la gracia para alcanzarla.' },
  'host': { term: 'Hostia', definition: 'El pan que se convierte en el cuerpo de Cristo en la consagración.' },
  'human-dignity': { term: 'Dignidad humana', definition: 'El valor fundamental de toda persona por estar hecha a imagen de Dios; el fundamento de la doctrina social de la Iglesia.' },
  'humility': { term: 'Humildad', definition: 'La virtud de reconocer la propia dependencia de Dios y de usar rectamente sus dones.' },
  'idolatry': { term: 'Idolatría', definition: 'Dar a una criatura el culto que se debe solo a Dios. Pecado contra el primer mandamiento.' },
  'immaculate-conception': { term: 'Inmaculada Concepción', definition: 'El dogma de que la Virgen María estuvo libre del pecado original desde el momento de su concepción. Se celebra el 8 de diciembre.' },
  'incarnation': { term: 'Encarnación', definition: 'La verdad de que el Hijo de Dios tomó carne humana y se hizo hombre en Jesucristo, plenamente Dios y plenamente hombre.' },
  'incense': { term: 'Incienso', definition: 'Sustancia aromática que se quema en el culto; su humo que sube es símbolo de la oración que asciende a Dios.' },
  'indulgence': { term: 'Indulgencia', definition: 'La remisión de la pena temporal debida por pecados ya perdonados, concedida por la Iglesia.' },
  'infallibility': { term: 'Infalibilidad', definition: 'El don por el que el papa y los obispos, bajo la acción del Espíritu Santo, quedan preservados del error al definir una enseñanza de fe o de moral.' },
  'intercession': { term: 'Intercesión', definition: 'Oración hecha en favor de otros.' },
  'jesus': { term: 'Jesús', definition: 'El Hijo de Dios que se hizo hombre para salvarnos. El nombre significa "Dios salva".' },
  'justice': { term: 'Justicia', definition: 'La virtud cardinal de dar a Dios y al prójimo lo que les corresponde.' },
  'justification': { term: 'Justificación', definition: 'El acto por el que Dios libra a una persona del pecado y la hace santa por su gracia.' },
  'kingdom-of-god': { term: 'Reino de Dios', definition: 'El reinado de Dios en los corazones humanos y el orden nuevo de amor que trae consigo.' },
  'kyrie': { term: 'Kyrie', definition: 'La oración "Señor, ten piedad", parte del acto penitencial al comienzo de la Misa.' },
  'laity': { term: 'Laicado', definition: 'Todos los miembros de la Iglesia que no están ordenados, llamados a llevar el Evangelio al mundo.' },
  'lamb-of-god': { term: 'Cordero de Dios', definition: 'Título de Cristo; también la oración que se canta al partir el pan, pidiendo misericordia y paz.' },
  'last-supper': { term: 'Última Cena', definition: 'La última comida que Jesús compartió con sus discípulos, en la que instituyó la Eucaristía. Se recuerda el Jueves Santo.' },
  'lectio-divina': { term: 'Lectio divina', definition: 'Lectura orante y meditativa de la Escritura, hecha con lentitud y reflexión.' },
  'lectionary': { term: 'Leccionario', definition: 'El libro que contiene las lecturas de la Escritura señaladas para la Misa de cada día.' },
  'lector': { term: 'Lector', definition: 'Quien proclama las lecturas de la Escritura en la Misa, salvo el Evangelio.' },
  'lent': { term: 'Cuaresma', definition: 'El tiempo de cuarenta días de oración, ayuno y penitencia antes de la Pascua.' },
  'limbo': { term: 'Limbo', definition: 'Idea teológica, nunca una doctrina definida, sobre el destino de quienes mueren sin bautismo y sin pecado personal.' },
  'liturgy': { term: 'Liturgia', definition: 'El culto público y oficial de la Iglesia, sobre todo la Misa.' },
  'liturgy-of-the-eucharist': { term: 'Liturgia eucarística', definition: 'La parte de la Misa en la que se preparan los dones, se reza la plegaria eucarística y se recibe la Comunión.' },
  'liturgy-of-the-hours': { term: 'Liturgia de las Horas', definition: 'La oración diaria oficial de la Iglesia, que santifica las horas del día con salmos, lecturas y oraciones.' },
  'liturgy-of-the-word': { term: 'Liturgia de la Palabra', definition: 'La parte de la Misa en la que se proclaman y se predican las Escrituras.' },
  'liturgical-year': { term: 'Año litúrgico', definition: 'El ciclo anual de tiempos y fiestas con el que la Iglesia celebra el misterio de Cristo.' },
  'lord-u2019s-day': { term: 'Día del Señor', definition: 'El domingo, día de la Resurrección de Cristo, santificado asistiendo a Misa y descansando del trabajo.' },
  'lord-u2019s-prayer': { term: 'Padre Nuestro', definition: 'La oración que enseñó Jesús, llamada la oración perfecta porque resume todo el Evangelio.' },
  'magisterium': { term: 'Magisterio', definition: 'La autoridad de enseñar de la Iglesia, ejercida por el papa y los obispos, que custodia e interpreta la fe.' },
  'magnificat': { term: 'Magníficat', definition: 'El cántico de alabanza de María en su visita a Isabel, que comienza "Proclama mi alma la grandeza del Señor".' },
  'manna': { term: 'Maná', definition: 'El pan que Dios dio milagrosamente a los israelitas en el desierto.' },
  'marks-of-the-church': { term: 'Notas de la Iglesia', definition: 'Los cuatro rasgos de la Iglesia de Cristo que se profesan en el Credo: una, santa, católica y apostólica.' },
  'martyr': { term: 'Mártir', definition: 'Quien sufre la muerte antes que renunciar a la fe en Cristo.' },
  'mary': { term: 'María', definition: 'La Madre de Jesús y, por tanto, Madre de Dios; honrada como la mayor de los santos.' },
  'mass': { term: 'Misa', definition: 'El acto central del culto católico, en el que se hace presente el sacrificio de Cristo y se recibe la Eucaristía.' },
  'matrimony': { term: 'Matrimonio', definition: 'El sacramento del matrimonio, alianza para toda la vida entre un hombre y una mujer, a imagen de la unión de Cristo y la Iglesia.' },
  'meditation': { term: 'Meditación', definition: 'Forma de oración que pone en juego la mente y el corazón para reflexionar sobre Dios y los misterios de la fe.' },
  'memorial': { term: 'Memoria', definition: 'Celebración litúrgica de rango menor, que conmemora a un santo en su día señalado.' },
  'messiah': { term: 'Mesías', definition: 'Del hebreo "el Ungido", el salvador prometido; en griego, "Cristo".' },
  'ministry': { term: 'Ministerio', definition: 'Servicio ofrecido para ayudar a la Iglesia a cumplir su misión.' },
  'miracle': { term: 'Milagro', definition: 'Signo del poder de Dios actuando, más allá de toda explicación natural.' },
  'missal': { term: 'Misal', definition: 'El libro que contiene las oraciones y los textos para la celebración de la Misa.' },
  'mitre': { term: 'Mitra', definition: 'El tocado alto y acabado en punta que lleva el obispo en las liturgias solemnes.' },
  'modesty': { term: 'Modestia', definition: 'La virtud de la moderación en el vestir, el hablar y el comportarse, que respeta la propia dignidad y la de los demás.' },
  'monastery': { term: 'Monasterio', definition: 'La casa comunitaria de los monjes o monjas que viven una vida apartada para la oración y el trabajo.' },
  'monk': { term: 'Monje', definition: 'Hombre que vive en una comunidad monástica bajo una regla, dedicado a la oración, al trabajo y a la gloria de Dios.' },
  'monotheism': { term: 'Monoteísmo', definition: 'La fe en un solo Dios.' },
  'monsignor': { term: 'Monseñor', definition: 'Título honorífico concedido por el papa a ciertos sacerdotes.' },
  'monstrance': { term: 'Ostensorio', definition: 'El vaso sagrado que sostiene la hostia y la expone para la adoración. También llamado custodia.' },
}

export default GLOSSARY_ES
